insert into famille_core.memberships(id,user_id,organization_id,app_id,status,joined_at) select x.mid,x.uid,x.oid,a.id,'active',now() from (values ('40000000-0000-0000-0000-000000000001'::uuid,'10000000-0000-0000-0000-000000000001'::uuid,'20000000-0000-0000-0000-000000000001'::uuid),('40000000-0000-0000-0000-000000000002'::uuid,'10000000-0000-0000-0000-000000000002'::uuid,'20000000-0000-0000-0000-000000000001'::uuid),('40000000-0000-0000-0000-000000000003'::uuid,'10000000-0000-0000-0000-000000000003'::uuid,'20000000-0000-0000-0000-000000000002'::uuid),('40000000-0000-0000-0000-000000000004'::uuid,'10000000-0000-0000-0000-000000000004'::uuid,'20000000-0000-0000-0000-000000000001'::uuid),('40000000-0000-0000-0000-000000000005'::uuid,'10000000-0000-0000-0000-000000000005'::uuid,'20000000-0000-0000-0000-000000000001'::uuid),('40000000-0000-0000-0000-000000000006'::uuid,'10000000-0000-0000-0000-000000000006'::uuid,'20000000-0000-0000-0000-000000000001'::uuid)) x(mid,uid,oid) cross join famille_core.applications a where a.code='kiosko' on conflict(user_id,organization_id,app_id) do nothing;
insert into famille_core.role_assignments(id,membership_id,app_id,organization_id,role_code,location_id,status) select x.aid,m.id,m.app_id,m.organization_id,x.rc,x.loc,'active' from (values ('50000000-0000-0000-0000-000000000001'::uuid,'40000000-0000-0000-0000-000000000001'::uuid,'owner'::text,null::uuid),('50000000-0000-0000-0000-000000000002'::uuid,'40000000-0000-0000-0000-000000000002'::uuid,'manager'::text,'30000000-0000-0000-0000-000000000001'::uuid),('50000000-0000-0000-0000-000000000003'::uuid,'40000000-0000-0000-0000-000000000003'::uuid,'owner'::text,null::uuid),('50000000-0000-0000-0000-000000000004'::uuid,'40000000-0000-0000-0000-000000000004'::uuid,'platform_admin'::text,null::uuid),('50000000-0000-0000-0000-000000000005'::uuid,'40000000-0000-0000-0000-000000000005'::uuid,'commercial'::text,null::uuid),('50000000-0000-0000-0000-000000000006'::uuid,'40000000-0000-0000-0000-000000000006'::uuid,'partner'::text,null::uuid)) x(aid,mid,rc,loc) join famille_core.memberships m on m.id=x.mid on conflict(id) do nothing;
insert into famille_core.plans(app_id,code,name,amount_fcfa,billing_period) select id,'basic','Basic',5000,'monthly' from famille_core.applications where code='kiosko' on conflict(app_id,code) do nothing;
insert into famille_core.subscriptions(id,organization_id,app_id,plan_id,status,starts_at,ends_at) select '60000000-0000-0000-0000-000000000001',o.id,a.id,p.id,'active',now()-interval '1 day',now()+interval '30 days' from famille_core.organizations o join famille_core.applications a on a.code='kiosko' join famille_core.plans p on p.app_id=a.id and p.code='basic' where o.id='20000000-0000-0000-0000-000000000001' on conflict(id) do nothing;
